"use client";

import { useEffect, useRef, useState } from "react";
import "./copy-feedback.css";

export interface CopyFeedbackProps {
  value: string;
  label?: string;
}

type CopyState = "idle" | "copying" | "copied" | "error";

async function writeClipboard(value: string) {
  if (window.isSecureContext && navigator.clipboard?.writeText) {
    await navigator.clipboard.writeText(value);
    return;
  }

  const previousFocus =
    document.activeElement instanceof HTMLElement ? document.activeElement : null;
  const field = document.createElement("textarea");

  try {
    field.value = value;
    field.readOnly = true;
    field.style.position = "fixed";
    field.style.opacity = "0";
    document.body.append(field);
    field.focus({ preventScroll: true });
    field.select();
    if (!document.execCommand("copy")) throw new Error("Clipboard unavailable");
  } finally {
    field.remove();
    if (previousFocus?.isConnected) previousFocus.focus({ preventScroll: true });
  }
}

export function CopyFeedback({ value, label = "Copy value" }: CopyFeedbackProps) {
  const [state, setState] = useState<CopyState>("idle");
  const resetTimer = useRef<number | null>(null);
  const inFlight = useRef(false);
  const mounted = useRef(true);
  const requestId = useRef(0);

  async function copy() {
    if (inFlight.current) return;
    inFlight.current = true;
    const currentRequest = ++requestId.current;
    if (resetTimer.current !== null) window.clearTimeout(resetTimer.current);
    resetTimer.current = null;
    setState("copying");

    let result: CopyState;
    try {
      await writeClipboard(value);
      result = "copied";
    } catch {
      result = "error";
    }

    if (!mounted.current || currentRequest !== requestId.current) return;
    inFlight.current = false;
    setState(result);
    resetTimer.current = window.setTimeout(() => {
      setState("idle");
      resetTimer.current = null;
    }, 1800);
  }

  useEffect(() => {
    requestId.current += 1;
    inFlight.current = false;
    if (resetTimer.current !== null) window.clearTimeout(resetTimer.current);
    resetTimer.current = null;
    setState("idle");
  }, [value]);

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      requestId.current += 1;
      inFlight.current = false;
      if (resetTimer.current !== null) window.clearTimeout(resetTimer.current);
    };
  }, []);

  return (
    <div className="tb-copy" data-state={state} aria-busy={state === "copying"}>
      <code className="tb-copy__value">{value}</code>
      <button
        aria-disabled={state === "copying"}
        className="tb-copy__button"
        onClick={copy}
        type="button"
      >
        {state === "copying"
          ? "Copying"
          : state === "copied"
            ? "Copied"
            : state === "error"
              ? "Try again"
              : label}
      </button>
      <span className="tb-copy__status" aria-live="polite">
        {state === "copying"
          ? "Copying value."
          : state === "copied"
            ? "Copied to clipboard."
            : state === "error"
              ? "Could not access the clipboard. Select and copy the value manually."
              : ""}
      </span>
    </div>
  );
}

.tb-copy {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  width: min(100%, 48rem);
  border: 1px solid #171918;
  background: #f7f7f2;
}

.tb-copy__value {
  min-width: 0;
  overflow-x: auto;
  padding: 1.15rem 1.25rem;
  color: #252826;
  font: 500 0.83rem/1.4 ui-monospace, SFMono-Regular, Consolas, monospace;
  white-space: nowrap;
  scrollbar-width: thin;
}

.tb-copy__button {
  appearance: none;
  min-width: 7.4rem;
  min-height: 3.75rem;
  padding: 0.8rem 1.1rem;
  color: #f7f7f2;
  border: 0;
  border-left: 1px solid #171918;
  background: #171918;
  font: 680 0.82rem/1 system-ui, sans-serif;
  cursor: pointer;
  touch-action: manipulation;
  transition: background-color 130ms ease-out;
}

@media (hover: hover) and (pointer: fine) {
  .tb-copy__button:hover {
    background: #3d423f;
  }
}

.tb-copy__button:active {
  background: #000;
}

.tb-copy__button[aria-disabled="true"] {
  color: #c9ccc8;
  background: #3d423f;
  cursor: wait;
}

.tb-copy[data-state="copied"] .tb-copy__button {
  color: #0c2a1b;
  background: #91edb1;
}

.tb-copy[data-state="error"] .tb-copy__button {
  color: #fff8f5;
  background: #b53c31;
}

.tb-copy__button:focus-visible {
  position: relative;
  z-index: 1;
  outline: 3px solid #d6ff55;
  outline-offset: -5px;
}

.tb-copy__status {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

@media (forced-colors: active) {
  .tb-copy,
  .tb-copy__button {
    border-color: ButtonText;
  }
}
